// Load all default commands. We import these for their side effect of loading
// using the plugin architecture via `common.register()`.
require('./src/cat');
require('./src/cd');
require('./src/chmod');
require('./src/cmd');
require('./src/cp');
require('./src/dirs');
require('./src/echo');
require('./src/exec');
